import java.util.Arrays;
public class Problem1_HeightLineUp { static void lineUp(int[] a){int pass=1;while(true){boolean swap=false;for(int j=0;j<a.length-1;j++)if(a[j]>a[j+1]){int t=a[j];a[j]=a[j+1];a[j+1]=t;swap=true;}System.out.println("Pass "+pass+++": "+Arrays.toString(a));if(!swap)break;}} public static void main(String[]x){lineUp(new int[]{4,2,5,1});}}